    --red: #d40a0a;
    --blue: #1350c4;
    --yellow: #f7c800;
    --ink: #0a0a0a;
    --paper: #faf8f2;
    --line: 10px;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  body {
    font-family: "Spectral", Georgia, serif;
    background: var(--paper);
    color: var(--ink);
    line-height: 1.6;
  }
  h1, h2, h3, .display {
    font-family: "Archivo Black", "Arial Black", sans-serif;
    text-transform: uppercase;
    letter-spacing: 0.01em;
    line-height: 1.05;
  }
  .wrap { max-width: 1120px; margin: 0 auto; padding: 0 24px; }

  /* Top bar: thin mondrian strip */
  .strip {
    display: grid;
    grid-template-columns: 3fr 1fr 1fr 5fr 2fr;
    height: 18px;
    border-bottom: var(--line) solid var(--ink);
  }
  .strip .r { background: var(--red); }
  .strip .b { background: var(--blue); }
  .strip .y { background: var(--yellow); }
  .strip .w { background: var(--paper); }
  .strip .k { background: var(--ink); }

  /* Hero: asymmetric mondrian grid */
  .hero {
    display: grid;
    grid-template-columns: 1.4fr 1fr 0.5fr;
    grid-template-rows: auto auto;
    border-bottom: var(--line) solid var(--ink);
  }
  .hero-copy {
    grid-column: 1 / 3;
    grid-row: 1 / 3;
    padding: 72px 48px 64px;
    border-right: var(--line) solid var(--ink);
    background: var(--paper);
  }
  .kicker {
    font-family: "Archivo Black", sans-serif;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.22em;
    display: inline-block;
    border: 4px solid var(--ink);
    padding: 6px 12px;
    margin-bottom: 28px;
    background: var(--yellow);
  }
  .hero h1 { font-size: clamp(2.2rem, 5.5vw, 4.4rem); max-width: 14ch; }
  .hero .sub {
    margin-top: 24px;
    font-size: 1.15rem;
    max-width: 46ch;
  }
  .hero-red {
    grid-column: 3;
    grid-row: 1;
    background: var(--red);
    border-bottom: var(--line) solid var(--ink);
    min-height: 180px;
  }
  .hero-blue {
    grid-column: 3;
    grid-row: 2;
    background: var(--blue);
  }
  .hero-yellow {
    grid-column: 1 / 2;
    border-top: var(--line) solid var(--ink);
    background: var(--paper);
    height: 56px;
  }
  .hero-tail {
    grid-column: 2 / 4;
    border-top: var(--line) solid var(--ink);
    border-left: var(--line) solid var(--ink);
    background: var(--yellow);
    height: 56px;
  }

  /* Facts band: four blocks like canvas cells */
  .facts {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    border-bottom: var(--line) solid var(--ink);
  }
  .fact {
    padding: 32px 24px;
    border-right: var(--line) solid var(--ink);
  }
  .fact:last-child { border-right: 0; }
  .fact .label {
    font-family: "Archivo Black", sans-serif;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.18em;
  }
  .fact .value {
    font-family: "Archivo Black", sans-serif;
    font-size: 1.35rem;
    margin-top: 10px;
    line-height: 1.2;
  }
  .fact.f-red { background: var(--red); color: #fff; }
  .fact.f-blue { background: var(--blue); color: #fff; }
  .fact.f-yellow { background: var(--yellow); }
  .fact.f-white { background: var(--paper); }

  /* Sections */
  section.block { border-bottom: var(--line) solid var(--ink); }
  .split {
    display: grid;
    grid-template-columns: 5fr 7fr;
  }
  .split.flip { grid-template-columns: 7fr 5fr; }
